import type { Resource } from './resource-model';
import type { Currency } from './currency-model';

export const ProjectStatusKeyToLabel = {
  'Draft': 'Draft',
  'Planning': 'Planning',
  'InProgress': 'In Progress',
  'OnHold': 'On Hold',
  'Completed': 'Completed',
  'Cancelled': 'Cancelled'
} as const;
export type ProjectStatusKey = keyof typeof ProjectStatusKeyToLabel;

export interface Project {
  /**
   * @displayName Project
   * @description Unique system identifier - GUID generated by system
   * @uiConstraints NEVER create input fields for this ID
   */
  id: string;
  /**
   * @displayName Project Name
   * @description Human-readable record identifier
   * @validationRule Required for create/update operations
   */
  projectName: string;
  /**
   * @displayName Budget
   * @validationRule Required for create/update operations
   */
  budget: number;
  /**
   * @displayName Budget (Base)
   */
  budgetBase?: number;
  /**
   * @displayName Created By
   * @validationRule Required for create/update operations
   */
  createdBy: Pick<Resource, 'id' | 'resourceName'>;
  /**
   * @displayName Created Date
   * @validationRule Required for create/update operations
   */
  createdDate: string;
  /**
   * @displayName Currency
   */
  currency?: Pick<Currency, 'id' | 'currencyName'>;
  /**
   * @displayName Delivery Lead
   * @validationRule Required for create/update operations
   */
  deliveryLead: Pick<Resource, 'id' | 'resourceName'>;
  /**
   * @displayName Description
   */
  description?: string;
  /**
   * @displayName End Date
   * @validationRule Required for create/update operations
   */
  endDate: string;
  /**
   * @displayName Exchange Rate
   */
  exchangeRate?: number;
  /**
   * @displayName Project Manager
   * @validationRule Required for create/update operations
   */
  projectManager: Pick<Resource, 'id' | 'resourceName'>;
  /**
   * @displayName Start Date
   * @validationRule Required for create/update operations
   */
  startDate: string;
  /**
   * @displayName Status
   * @validationRule Required for create/update operations
   */
  statusKey: ProjectStatusKey;
}

export const _Project = 'Project' as const;